export function generateSportShoes(): ProductSeedItem[] {
  return sportShoesData.map((s) => {
    const desc = `### 1. Tổng quan & Định vị sản phẩm
${s.name} là sản phẩm giày thể thao và chạy bộ đỉnh cao từ thương hiệu thể thao hàng đầu ${s.brand}. Được kiểm nghiệm bởi các vận động viên chuyên nghiệp trên các đường chạy khắc nghiệt nhất thế giới, sản phẩm đem lại hiệu suất bứt tốc vượt bậc, độ êm ái tối đa và khả năng bảo vệ đôi chân toàn diện.

### 2. Thông số kỹ thuật chi tiết (Technical Specifications)
- **Thương hiệu:** ${s.brand}
- **Công nghệ đế đệm (Midsole):** ${s.sole}
- **Tấm trợ lực (Carbon Plate / Torsion System):** ${s.plate}
- **Chất liệu thân trên (Upper):** ${s.upper}
- **Trọng lượng giày:** ${s.weight}
- **Độ dốc gót-mũi (Heel Drop) & Độ bám sân:** ${s.drop}
- **Bảng size chân tiêu chuẩn:** Đầy đủ các size từ 39 đến 45 (EUR)

### 3. Ưu điểm nổi trội & Khả năng vận động
- Hoàn trả năng lượng vượt bậc, giảm thiểu tối đa hiện tượng mỏi cơ bắp chân và bảo vệ khớp đầu gối khi chạy cự ly dài.
- Thân giày ôm khít mu bàn chân, thoáng khí thoát mồ hôi nhanh chóng ngăn ngừa phồng rộp da chân.

### 4. Đối tượng & Cự ly phù hợp
- Dành cho chân chạy phong trào đến chuyên nghiệp thi đấu cự ly 5km, 10km, 21km Half Marathon và 42km Full Marathon hoặc tập luyện gym thể thao hàng ngày.`;

    const variants = s.colors.map((c, idx) => ({
      attributes: { color: c, size: '42', brand: s.brand },
      price: s.price,
      stock_quantity: 35 + idx * 6
    }));

    return {
      name: s.name,
      categorySlug: 'sport-shoes',
      brand: s.brand,
      price: s.price,
      description: desc,
      images: TECH_IMAGES.shoes,
      variants
    };
  });
}

