export function generateOutdoor(): ProductSeedItem[] {
  return outdoorData.map((o) => {
    const desc = `### 1. Tổng quan & Định vị sản phẩm
${o.name} là trang thiết bị thể thao dã ngoại, xe đạp và cắm trại cao cấp từ thương hiệu ${o.brand}. Sản phẩm được chế tạo theo các tiêu chuẩn kỹ thuật an toàn quốc tế, giúp người đam mê xê dịch tự tin chinh phục những cung đường thử thách và tận hưởng trọn vẹn thiên nhiên hoang dã.

### 2. Thông số kỹ thuật chi tiết (Technical Specifications)
- **Thương hiệu:** ${o.brand}
- **Vật liệu khung & Kết cấu cơ khí:** ${o.frame}
- **Khả năng chịu lực & Kháng thời tiết:** ${o.fly}
- **Cơ chế vận hành & Tính năng an toàn:** ${o.inner}
- **Kích thước sử dụng & Kích thước gấp gọn:** ${o.size}
- **Trọng lượng & Quy cách đóng gói:** ${o.pack}

### 3. Ưu điểm vượt trội
- Bền bỉ trong điều kiện thời tiết nhiệt đới khắc nghiệt (nắng gắt, mưa lớn, ẩm mốc), chịu va đập và mài mòn cao.
- Trọng lượng nhẹ, cơ chế gấp gọn hoặc tháo lắp nhanh giúp việc chuyên chở trên xe máy, ô tô hay balo trở nên dễ dàng.

### 4. Đối tượng & Hoàn cảnh sử dụng
- Người chơi xe đạp thể thao, phượt thủ đi tour dài ngày, gia đình cắm trại cuối tuần (camping/glamping) và người yêu thích trekking khám phá rừng núi.`;

    const variants = o.colors.map((c, idx) => ({
      attributes: { color: c, brand: o.brand },
      price: o.price,
      stock_quantity: 25 + idx * 5
    }));

    return {
      name: o.name,
      categorySlug: 'camping-outdoor',
      brand: o.brand,
      price: o.price,
      description: desc,
      images: TECH_IMAGES.outdoor,
      variants
    };
  });
}

