export function generateSkincare(): ProductSeedItem[] {
  return skincareData.map((s) => {
    const desc = `### 1. Giới thiệu tổng quan & Định vị sản phẩm
${s.name} là dược mỹ phẩm chăm sóc da chuyên sâu chính hãng từ thương hiệu danh tiếng ${s.brand}. Được các chuyên gia da liễu hàng đầu thế giới khuyên dùng, sản phẩm mang lại giải pháp chăm sóc làn da khoa học, an toàn lành tính và đạt hiệu quả lâm sàng rõ rệt trên làn da người châu Á.

### 2. Thông số kỹ thuật chi tiết (Technical Specifications)
- **Thương hiệu:** ${s.brand}
- **Dung tích / Quy cách đóng gói:** ${s.vol}
- **Phân loại sản phẩm:** ${s.type}
- **Thành phần hoạt tính chính (Key Ingredients):** ${s.ing}
- **Loại da phù hợp:** ${s.skin}
- **Hiệu quả điều trị & Lợi ích nổi trội:** ${s.benefit}
- **Kết cấu sản phẩm (Texture):** ${s.texture}
- **Tiêu chuẩn an toàn:** Không chứa cồn khô, không Paraben, không hương liệu tổng hợp độc hại, đạt chứng nhận da liễu quốc tế

### 3. Công nghệ nổi bật
- Công thức nồng độ chuẩn khoa học giúp đưa dưỡng chất vào sâu tầng hạ bì mà không phá vỡ hàng rào bảo vệ sinh học tự nhiên của da.
- Làm dịu kích ứng và phục hồi màng bảo vệ da nhanh chóng chỉ sau một thời gian ngắn sử dụng.

### 4. Hướng dẫn sử dụng & Thứ tự Skincare
- Sử dụng hàng ngày sau bước làm sạch và cân bằng toner, lấy lượng vừa đủ thoa đều và vỗ nhẹ lên da mặt để tinh chất thẩm thấu tối đa.`;

    const variants = s.colors.map((c, idx) => ({
      attributes: { color: c, brand: s.brand },
      price: s.price,
      stock_quantity: 40 + idx * 10
    }));

    return {
      name: s.name,
      categorySlug: 'skin-care',
      brand: s.brand,
      price: s.price,
      description: desc,
      images: TECH_IMAGES.skincare,
      variants
    };
  });
}

