export function generatePerfumes(): ProductSeedItem[] {
  return perfumeData.map((p) => {
    const desc = `### 1. Giới thiệu tổng quan & Định vị sản phẩm
${p.name} là tác phẩm nghệ thuật mùi hương cao cấp từ nhà mốt nước hoa danh tiếng ${p.brand}. Được pha chế bởi những bậc thầy điều chế hương (Master Perfumer) từ những tinh dầu hoa cỏ, gỗ quý và gia vị phương Đông đắt đỏ bậc nhất, mùi hương là chữ ký vô hình định hình khí chất và sự quyến rũ khó quên của bạn.

### 2. Thông số kỹ thuật chi tiết (Technical Specifications)
- **Thương hiệu:** ${p.brand}
- **Nồng độ tinh dầu (Concentration):** ${p.con}
- **Hương đầu (Top Notes):** ${p.top}
- **Hương giữa (Middle / Heart Notes):** ${p.mid}
- **Hương cuối (Base Notes):** ${p.base}
- **Độ tỏa hương & Độ lưu hương (Sillage & Longevity):** ${p.sillage}
- **Phong cách & Hoàn cảnh sử dụng tối ưu:** ${p.occ}

### 3. Kim tự tháp mùi hương & Trải nghiệm
- Chuyển biến 3 tầng hương mượt mà, từ nốt mở đầu tươi mát bừng sáng, chuyển sang tầng hương giữa ngọt ngào đài các và đọng lại tầng hương cuối trầm ấm sâu lắng trên da thịt suốt ngày dài.
- Tinh dầu thơm nồng độ cao giúp hương thơm bền bỉ không bị biến đổi mùi khi cơ thể vận động ra mồ hôi.

### 4. Lời khuyên xịt nước hoa chuẩn xác
- Xịt lên các điểm mạch đập có nhiệt độ cơ thể ấm áp (sau tai, cổ tay, hõm ngực, gáy cổ) ở cự ly 15-20cm để hương thơm khuếch tán tự nhiên và tỏa hương xa nhất.`;

    const variants = p.colors.map((c, idx) => ({
      attributes: { color: c, brand: p.brand },
      price: p.price,
      stock_quantity: 30 + idx * 5
    }));

    return {
      name: p.name,
      categorySlug: 'perfume',
      brand: p.brand,
      price: p.price,
      description: desc,
      images: TECH_IMAGES.perfume,
      variants
    };
  });
}
